'use strict'

import soundManager from '../service/sound-manager'
import HitboxManager from '../service/hitbox-manager'
import resource from '../resource'
import { CLOUD_FRAME_STEPS, drawImage } from './enemies/common'
import { MAP_TYPE_WORLD, SOUND_RECORDER, SOUND_SECRET, SECRET_WHISTLE, TILE_WIDTH, TILE_HEIGHT, LINK_DIRECTION_EAST, LINK_DIRECTION_NORTH } from '../constant'

// The whistle, measured in the ROM (bank 7, $EF71; bank 1, $A0A8). Link stands still while the song plays,
// then on the screen of the lake of level 7 the water drains away; anywhere else on the overworld, if Link
// has a piece of the Triforce, a whirlwind comes from the left edge and takes him to a level. It does
// nothing in the caves
export const WHISTLE_STEPS = 150

// Where the whirlwind takes Link, level by level: the screen of the level and the line of the tile it leaves
// him on, always in column 8
const LEVELS = [
  { column: 7, line: 3, tileLine: 5 },
  { column: 12, line: 3, tileLine: 7 },
  { column: 4, line: 7, tileLine: 5 },
  { column: 5, line: 4, tileLine: 5 },
  { column: 11, line: 0, tileLine: 7 },
  { column: 2, line: 2, tileLine: 5 },
  { column: 2, line: 4, tileLine: 7 },
  { column: 13, line: 6, tileLine: 2 }
]
const DROP_COLUMN = 8

// The whirlwind (object $5E) comes out of a cloud and goes along its line, 2 NES pixels a frame; it catches
// Link when it reaches him (8 NES pixels away), or leaves the screen without him. Its sprite changes palette
// and turns over every frame
const WHIRLWIND_SPEED = 4
const CLOUD_STEPS = 3 * CLOUD_FRAME_STEPS
const CATCH_DISTANCE = TILE_WIDTH / 2
const WHIRLWIND_FRAMES = 4

// The water changes colour 10 times, every 8 frames from the end of the song, then the bed and the stairs
// show 13 frames after the last colour (sound of the secret). The sprites of the lake are named
// lake_<colour>_<part>, colour 0 for the water
const DRAIN_COLOURS = 10
const DRAIN_COLOUR_STEPS = 8
const DRAIN_REVEAL_STEP = 85
const LAKE_SPRITE = /^lake_\d+_/

// Played on the overworld only. True if Link plays it
export function playWhistle (map) {
  if (map.type !== MAP_TYPE_WORLD) {
    return false
  }
  soundManager.play(resource.getSound(SOUND_RECORDER))
  return true
}

// The song is over: the lake drains (once until Link leaves), or the whirlwind comes on Link's line
export function endWhistle (map, link) {
  const lake = [...map.tilesIterator()].filter(tile => tile.destructible === SECRET_WHISTLE)
  if (lake.length > 0) {
    if (lake.some(tile => tile.isHidden) && !map.whistles.some(effect => effect instanceof LakeDrain)) {
      map.whistles.push(new LakeDrain(lake))
    }
    return
  }
  const target = nextLevel(link)
  if (target && !map.whistles.some(effect => effect instanceof Whirlwind)) {
    map.whistles.push(new Whirlwind(map.x, link.y, target))
  }
}

// The next level whose piece of the Triforce Link has, after the last one the whirlwind went to: forward when
// he faces east or north, backward otherwise
function nextLevel (link) {
  const owned = link.inventory.triforce
  if (owned.length === 0) {
    return undefined
  }
  const step = link.direction === LINK_DIRECTION_EAST || link.direction === LINK_DIRECTION_NORTH ? 1 : -1
  let index = link.whirlwindLevel
  do {
    index = (index + step + LEVELS.length) % LEVELS.length
  } while (!owned.includes(index + 1))
  link.whirlwindLevel = index
  return LEVELS[index]
}

// On the screen of the level, another whirlwind brings Link in from the left edge to column 8
export function bringIn (map, link, target) {
  const whirlwind = new Whirlwind(map.x, link.y, target, map.x + DROP_COLUMN * TILE_WIDTH)
  whirlwind.carry(link)
  map.whistles.push(whirlwind)
}

export class Whirlwind {
  constructor (x, y, target, dropX) {
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.target = target
    // Where it leaves Link; undefined: it takes him off the right edge
    this.dropX = dropX
    this.link = undefined
    this.steps = 0
    // At the right edge with Link: the game takes them to the level
    this.leaving = false
    this.done = false
  }

  carry (link) {
    this.link = link
    link.carried = this
    link.direction = LINK_DIRECTION_EAST
    link.resetActions()
    link.stopWalking()
    this.moveLink()
  }

  moveLink () {
    this.link.x = this.x
    this.link.y = this.y
    this.link.hitbox = HitboxManager.compute(this.link)
  }

  process (map, link) {
    this.steps++
    if (this.steps <= CLOUD_STEPS || this.leaving) {
      return
    }
    this.x += WHIRLWIND_SPEED
    if (!this.link && !link.carried && Math.abs(link.y - this.y) < TILE_HEIGHT / 2 && Math.abs(link.x - this.x) <= CATCH_DISTANCE) {
      this.carry(link)
    }
    if (!this.link) {
      this.done = this.x >= map.x + map.width
      return
    }
    if (this.dropX !== undefined && this.x >= this.dropX) {
      this.x = this.dropX
      this.moveLink()
      this.link.carried = undefined
      this.done = true
      return
    }
    if (this.dropX === undefined && this.x >= map.x + map.width - this.width) {
      this.x = map.x + map.width - this.width
      this.leaving = true
    }
    this.moveLink()
  }

  draw (context) {
    if (this.steps <= CLOUD_STEPS) {
      drawImage(context, resource.getSprite('misc_bomb_blow'), Math.floor((this.steps - 1) / CLOUD_FRAME_STEPS), this.x, this.y, this.width, this.height)
      return
    }
    drawImage(context, resource.getSprite('whirlwind'), this.steps % WHIRLWIND_FRAMES, this.x, this.y, this.width, this.height)
  }
}

export class LakeDrain {
  constructor (tiles) {
    this.tiles = tiles
    this.steps = 0
    this.done = false
  }

  process () {
    const colour = this.steps / DRAIN_COLOUR_STEPS + 1
    if (Number.isInteger(colour) && colour <= DRAIN_COLOURS) {
      for (const tile of this.tiles) {
        tile.sprite = resource.getSprite(tile.original.sprite.name.replace(LAKE_SPRITE, `lake_${colour}_`)) ?? tile.sprite
      }
    }
    if (this.steps === DRAIN_REVEAL_STEP) {
      for (const tile of this.tiles) {
        tile.reveal()
      }
      soundManager.play(resource.getSound(SOUND_SECRET))
      this.done = true
    }
    this.steps++
  }

  draw () {}
}
