'use strict'

import textManager from '../service/text-manager'
import { SPRITE_TEXT_WIDTH } from '../constant'

// One line of the bitmap font, centred on the screen width, enlarged scale times
export function drawCenteredText (context, text, color, screenWidth, y, scale = 1) {
  const width = text.length * SPRITE_TEXT_WIDTH * scale
  context.save()
  context.imageSmoothingEnabled = false
  context.translate(Math.round((screenWidth - width) / 2), y)
  context.scale(scale, scale)
  textManager.drawLine(context, text, color, 0, 0)
  context.restore()
}
